  ('Crossbody Bag Saddle', 75, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=crossbody%20bag%20saddle%2C%20on%20a%20cream%20background%2C%20soft%20shadows%2C%20editorial%20fashion%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Crossbody%20Bag%20Saddle', NULL, ARRAY['for-her','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'high', 'Full-grain leather, adjustable strap. The bag that holds your day.', 'Fits phone, wallet, keys, lipstick. Hands-free and stylish.'),
  ('Bath Bomb Gift Set', 26, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=bath%20bomb%20gift%20set%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Bath%20Bomb%20Gift%20Set', NULL, ARRAY['for-her','for-kids']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Six handmade bombs, natural essential oils. For the long bath.', 'The colors are natural, not neon. The lavender one is my favorite.'),
  ('Jade Roller and Gua Sha', 18, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=jade%20roller%20and%20gua%20sha%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Jade%20Roller%20and%20Gua%20Sha', NULL, ARRAY['for-her','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Cool stone, gentle pressure. The morning ritual that feels like self-respect.', 'Five minutes a day and my face looks less puffy. Not magic, but close.'),
  ('Eucalyptus Shower Bundle', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=eucalyptus%20shower%20bundle%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Eucalyptus%20Shower%20Bundle', NULL, ARRAY['for-her','for-him','for-parents']::text[], ARRAY['thanks','birthday']::text[], 'cheap', 'Hang it in the shower. Steam releases the scent. Spa at home.', 'Walked in and thought I was at a spa. The smell is real eucalyptus.'),
  ('Lavender Pillow Mist', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=lavender%20pillow%20mist%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Lavender%20Pillow%20Mist', NULL, ARRAY['for-her','for-parents','for-friends']::text[], ARRAY['thanks','christmas']::text[], 'cheap', 'French lavender, chamomile. Two sprays and the pillow knows it''s time.', 'I was skeptical. Then I slept nine hours straight.'),
  ('Hand Cream Trio', 24, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=hand%20cream%20trio%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Hand%20Cream%20Trio', NULL, ARRAY['for-her','for-coworkers','for-parents']::text[], ARRAY['thanks','christmas']::text[], 'cheap', 'Shea butter, three scents. For hands that wash too often.', 'Non-greasy, absorbs fast. The linen scent is addictive.'),
  ('Silk Scrunchies Set', 14, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=silk%20scrunchies%20set%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Silk%20Scrunchies%20Set', NULL, ARRAY['for-her','for-kids','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Mulberry silk, gentle on hair. No crease, no pull.', 'No more ponytail dent. Also they don''t slide off at night.'),
  ('Cuticle Oil Pen', 12, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=cuticle%20oil%20pen%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Cuticle%20Oil%20Pen', NULL, ARRAY['for-her','for-coworkers']::text[], ARRAY['thanks','birthday']::text[], 'cheap', 'Jojoba and vitamin E. Click-pen, no mess. For nails that need a kind word.', 'One week of use and my nails stopped peeling. Simple but effective.'),
  ('Dry Body Brush', 15, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=dry%20body%20brush%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Dry%20Body%20Brush', NULL, ARRAY['for-her','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Natural bristles, long handle. Skin that feels awake before coffee.', 'Two minutes before showering. Skin is smoother, no lotion needed.'),
  ('Eye Mask Gel Bead', 14, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=eye%20mask%20gel%20bead%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Eye%20Mask%20Gel%20Bead', NULL, ARRAY['for-her','for-him','for-coworkers']::text[], ARRAY['thanks','birthday']::text[], 'cheap', 'Hot or cold therapy. For the screen-tired eyes.', 'Pop it in the fridge. Twenty minutes and my eyes feel human again.'),
  ('Aromatherapy Roll-On Set', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=aromatherapy%20roll-on%20set%2C%20on%20a%20stone%20surface%2C%20soft%20diffused%20light%2C%20editorial%20beauty%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Aromatherapy%20Roll-On%20Set', NULL, ARRAY['for-her','for-friends','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Three blends: focus, calm, sleep. Pocket-sized, purse-ready.', 'The sleep one works. I roll it on my wrists and wind down.');
INSERT INTO public.products (name, price, image_url, affiliate_url, asin, audience_tags, occasion_tags, price_range, description, review_quote) VALUES
  ('Hardcover Journal Lined', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=hardcover%20journal%20lined%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Hardcover%20Journal%20Lined', NULL, ARRAY['for-her','for-him','for-friends']::text[], ARRAY['birthday','newyear']::text[], 'cheap', 'Smyth-sewn binding, 240 pages, lays flat. The kind that lasts.', 'Opens flat, paper takes ink without bleed. My third one now.'),
  ('Fountain Pen Medium Nib', 28, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=fountain%20pen%20medium%20nib%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Fountain%20Pen%20Medium%20Nib', NULL, ARRAY['for-him','for-friends','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Cartridge or converter. The scratch of real ink on paper.', 'First fountain pen. The line is smooth, the ink flows. Writing feels different.'),
  ('Leather Notebook Cover A5', 35, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=leather%20notebook%20cover%20a5%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Leather%20Notebook%20Cover%20A5', NULL, ARRAY['for-him','for-her','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Full-grain leather, refillable. Your notebook''s forever home.', 'Looks better scuffed. The elastic holds refills tight.'),
  ('Watercolor Pencil Set 24', 25, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=watercolor%20pencil%20set%2024%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Watercolor%20Pencil%20Set%2024', NULL, ARRAY['for-her','for-kids','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Draw, then brush with water. Color that blooms.', 'Vibrant, smooth, blend beautifully. My sketchbook got interesting.'),
  ('Book Lovers Tea Sampler', 24, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=book%20lovers%20tea%20sampler%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Book%20Lovers%20Tea%20Sampler', NULL, ARRAY['for-her','for-parents','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Six loose-leaf teas, each paired with a reading mood.', 'The ''rainy afternoon'' blend is my reading companion now.'),
  ('Desk Organizer Walnut', 39, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=desk%20organizer%20walnut%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Desk%20Organizer%20Walnut', NULL, ARRAY['for-him','for-coworkers','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Solid wood, six slots. For the desk that wants to grow up.', 'Heavy, beautiful, and everything has a place now.'),
  ('Wax Seal Stamp Kit', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=wax%20seal%20stamp%20kit%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Wax%20Seal%20Stamp%20Kit', NULL, ARRAY['for-her','for-friends']::text[], ARRAY['anniversary','thanks']::text[], 'cheap', 'Brass stamp, wax beads, melting spoon. Letters worth opening.', 'Sealed my wedding thank-you cards with this. People kept the envelopes.'),
  ('Bullet Dotted Notebook', 18, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=bullet%20dotted%20notebook%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Bullet%20Dotted%20Notebook', NULL, ARRAY['for-her','for-him','for-friends']::text[], ARRAY['newyear','birthday']::text[], 'cheap', '120gsm paper, no bleed-through. The system that actually sticks.', 'Dots instead of lines. Freedom to plan, sketch, and note in one place.'),
  ('Calligraphy Brush Pen Set', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=calligraphy%20brush%20pen%20set%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Calligraphy%20Brush%20Pen%20Set', NULL, ARRAY['for-her','for-kids','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Dual-tip, flexible brush. For the handwriting that wants to wander.', 'The pressure sensitivity is real. Lettering finally clicked.'),
  ('Reading Light Clip-On Warm', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=reading%20light%20clip-on%20warm%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Reading%20Light%20Clip-On%20Warm', NULL, ARRAY['for-her','for-parents','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Amber light, three brightness levels. For the ''one more chapter'' nights.', 'No blue light, no disturbing partner. Clips to any book.'),
  ('Insulated Water Bottle 32oz', 28, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=insulated%20water%20bottle%2032oz%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Insulated%20Water%20Bottle%2032oz', NULL, ARRAY['for-him','for-her','for-kids','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Keeps ice for 24 hours. The bottle that lives on your desk.', 'Left it in a hot car. Still had ice six hours later.'),
  ('Yoga Mat Cork', 42, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=yoga%20mat%20cork%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Yoga%20Mat%20Cork', NULL, ARRAY['for-her','for-parents','for-friends']::text[], ARRAY['newyear','birthday']::text[], 'mid', 'Natural cork surface, no slip. Better grip when wet.', 'No more sliding in downward dog. The cork feels grounded.'),
  ('Resistance Band Set', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=resistance%20band%20set%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Resistance%20Band%20Set', NULL, ARRAY['for-him','for-her','for-parents']::text[], ARRAY['newyear','birthday']::text[], 'cheap', 'Five bands, door anchor, handles. The gym that fits in a drawer.', 'Surprised by the resistance. The red one is no joke.'),
  (' Camping Hammock Double', 38, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%20camping%20hammock%20double%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=%20Camping%20Hammock%20Double', NULL, ARRAY['for-him','for-friends','for-kids']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Parachute nylon, 500lb capacity. The park just became a bedroom.', 'Packs to the size of a grapefruit. Set up in two minutes.'),
  ('Insulated Travel Mug 16oz', 32, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=insulated%20travel%20mug%2016oz%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Insulated%20Travel%20Mug%2016oz', NULL, ARRAY['for-him','for-her']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Keeps coffee hot from nine to three.', 'He forgets to drink water. Let the mug remind him instead of you.'),
  ('Folding Camp Chair', 35, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=folding%20camp%20chair%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Folding%20Camp%20Chair', NULL, ARRAY['for-him','for-friends','for-parents']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Aluminum frame, cup holder, packs flat. Your backstage seat anywhere.', 'Lighter than expected. The cup holder is the real luxury.'),
  ('Jump Rope Weighted', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=jump%20rope%20weighted%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Jump%20Rope%20Weighted', NULL, ARRAY['for-him','for-her','for-friends']::text[], ARRAY['newyear','birthday']::text[], 'cheap', 'Steel cable, ball bearing. The cardio you can do in 10 square feet.', 'Fast, smooth, no tangling. Calves burning in 3 minutes.'),
  ('Golf Towel Microfiber', 14, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=golf%20towel%20microfiber%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Golf%20Towel%20Microfiber', NULL, ARRAY['for-him','for-parents','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Tri-fold, carabiner clip. For the golfer who cares about their clubs.', 'Absorbs moisture without scratching. The clip stays put.'),
  ('Running Belt Slim', 15, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=running%20belt%20slim%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Running%20Belt%20Slim', NULL, ARRAY['for-her','for-him','for-friends']::text[], ARRAY['birthday','newyear']::text[], 'cheap', 'Phone, keys, card. No bounce, no chafe. Forget it''s there.', 'Ran a half marathon with this. Phone didn''t move an inch.'),
  ('Picnic Blanket Waterproof', 29, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=picnic%20blanket%20waterproof%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Picnic%20Blanket%20Waterproof', NULL, ARRAY['for-friends','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Folds to a tote, unfolds to a table for four. Sand and grass proof.', 'The backing is truly waterproof. Sat on damp grass, stayed dry.'),
  ('Board Game Strategy Set', 39, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=board%20game%20strategy%20set%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Board%20Game%20Strategy%20Set', NULL, ARRAY['for-friends','for-him','for-her']::text[], ARRAY['christmas','birthday']::text[], 'mid', 'For the game night that doesn''t end at Monopoly.', 'Played three rounds straight. The strategy depth is real.'),
  ('1000 Piece Puzzle Art', 24, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=1000%20piece%20puzzle%20art%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=1000%20Piece%20Puzzle%20Art', NULL, ARRAY['for-parents','for-her','for-friends']::text[], ARRAY['christmas','birthday']::text[], 'cheap', 'Riverside scene, matte finish. The quiet weekend activity.', 'Took us four evenings. The satisfaction of the last piece is worth it.'),
  ('Building Blocks Classic', 35, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=building%20blocks%20classic%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Building%20Blocks%20Classic', NULL, ARRAY['for-kids','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'mid', '500 pieces, six colors. For the engineer who hasn''t retired.', 'My 8-year-old built a spaceship. My 38-year-old self helped.'),
  ('Card Game Party Pack', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=card%20game%20party%20pack%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Card%20Game%20Party%20Pack', NULL, ARRAY['for-friends','for-coworkers']::text[], ARRAY['christmas','thanks']::text[], 'cheap', 'Three games, 2-8 players. The icebreaker that actually breaks ice.', 'Played with strangers. We were laughing in five minutes.'),
  ('Wooden Brain Teaser Set', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=wooden%20brain%20teaser%20set%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Wooden%20Brain%20Teaser%20Set', NULL, ARRAY['for-him','for-kids','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Six metal and wood puzzles. For the mind that needs a walk.', 'Some took minutes, one took days. All satisfying to solve.'),
  ('RC Stunt Car', 32, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=rc%20stunt%20car%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=RC%20Stunt%20Car', NULL, ARRAY['for-kids']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Flips, spins, climbs. The remote control car that grew up.', 'My kid drove it down the stairs. Still works. Sturdy is an understatement.'),
  ('Art Kit for Kids 120pcs', 26, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=art%20kit%20for%20kids%20120pcs%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Art%20Kit%20for%20Kids%20120pcs', NULL, ARRAY['for-kids']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Crayons, markers, paints, paper. The creative explosion in a box.', 'Everything in one case. My 6-year-old opened it and didn''t surface for hours.'),
  ('Stargazing Telescope Entry', 79, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=stargazing%20telescope%20entry%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Stargazing%20Telescope%20Entry', NULL, ARRAY['for-kids','for-him','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'high', '70mm aperture, tripod, phone adapter. The moon, up close.', 'Saw Saturn''s rings. My kids thought it was a picture. It wasn''t.'),
  ('Jigsaw Puzzle Map World', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=jigsaw%20puzzle%20map%20world%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Jigsaw%20Puzzle%20Map%20World', NULL, ARRAY['for-kids','for-parents','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Vintage world map, 500 pieces. Geography you can touch.', 'My son now knows where Mongolia is. That''s the power of a puzzle.'),
  ('Magnetic Dart Board', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=magnetic%20dart%20board%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Magnetic%20Dart%20Board', NULL, ARRAY['for-kids','for-coworkers','for-him']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'No sharp points, no wall holes. The office tournament starter.', 'Safer than real darts, almost as satisfying. The magnets stick well.'),
  ('Gourmet Chocolate Box 24pc', 35, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=gourmet%20chocolate%20box%2024pc%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Gourmet%20Chocolate%20Box%2024pc', NULL, ARRAY['for-her','for-parents','for-coworkers']::text[], ARRAY['birthday','thanks','christmas']::text[], 'mid', 'Single-origin, hand-tempered. The box that doesn''t last.', 'The sea salt caramel disappeared first. The dark cherry was my favorite.'),
  ('Coffee Bean Sampler 1lb', 28, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=coffee%20bean%20sampler%201lb%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Coffee%20Bean%20Sampler%201lb', NULL, ARRAY['for-him','for-her','for-friends','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Three origins, whole bean. For the cup that''s never the same.', 'The Ethiopian blew me away. Blueberry in coffee? Yes.'),
  ('Honey Trio Gift Set', 24, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=honey%20trio%20gift%20set%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Honey%20Trio%20Gift%20Set', NULL, ARRAY['for-parents','for-her','for-friends']::text[], ARRAY['thanks','birthday']::text[], 'cheap', 'Wildflower, clover, buckwheat. Three honeys, three toast moods.', 'The buckwheat is dark and malty. Never knew honey could taste like this.'),
  ('Matcha Powder Ceremonial', 32, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=matcha%20powder%20ceremonial%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Matcha%20Powder%20Ceremonial', NULL, ARRAY['for-her','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'First harvest, stone-ground. The green that''s actually green.', 'Froths to a creamy jade. Smooth, no bitterness. Worth the price.'),
  ('Hot Sauce Gift Set', 26, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=hot%20sauce%20gift%20set%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Hot%20Sauce%20Gift%20Set', NULL, ARRAY['for-him','for-friends','for-parents']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Five small-batch hot sauces. For the one who likes it loud.', 'The habanero-mango is the best hot sauce I''ve had this year.'),
  ('Tea Sampler Tin Set', 29, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=tea%20sampler%20tin%20set%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Tea%20Sampler%20Tin%20Set', NULL, ARRAY['for-her','for-parents','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Six loose-leaf tins. The shelf looks like a tea shop.', 'Each tin has its own character. The oolong is my evening ritual.'),
  ('Olive Oil Trio', 35, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=olive%20oil%20trio%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Olive%20Oil%20Trio', NULL, ARRAY['for-parents','for-friends','for-coworkers']::text[], ARRAY['thanks','christmas']::text[], 'mid', 'Single-variety, cold-pressed. For the cook who drizzles with intention.', 'The Frantoio is grassy and peppery. Tastes alive.'),
  ('Pasta Making Kit', 32, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=pasta%20making%20kit%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Pasta%20Making%20Kit', NULL, ARRAY['for-her','for-him','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Roller, cutter, drying rack. Flour becomes dinner.', 'First batch was ugly but delicious. Third batch was beautiful.'),
  ('Craft Beer Sampler 12pk', 42, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=craft%20beer%20sampler%2012pk%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Craft%20Beer%20Sampler%2012pk', NULL, ARRAY['for-him','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Twelve styles from twelve breweries. The tour without the driving.', 'The sour was a revelation. Didn''t know I liked sours until now.'),
  ('Smoked Salmon Gift Box', 45, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=smoked%20salmon%20gift%20box%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Smoked%20Salmon%20Gift%20Box', NULL, ARRAY['for-parents','for-her','for-him']::text[], ARRAY['christmas','thanks']::text[], 'mid', 'Cold-smoked, two sides. The brunch that feels like a hotel.', 'Silky, smoky, perfectly sliced. With cream cheese on a bagel — heaven.'),
  ('Gallery Wall Frame Set', 42, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=gallery%20wall%20frame%20set%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Gallery%20Wall%20Frame%20Set', NULL, ARRAY['for-her','for-parents','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Five oak frames, mixed sizes. The wall that tells a story.', 'Hung them in the hallway. The wall went from blank to intentional.'),
  ('Tabletop Easel Stand', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=tabletop%20easel%20stand%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Tabletop%20Easel%20Stand', NULL, ARRAY['for-her','for-friends','for-kids']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Solid beech wood, adjustable. For the art that deserves a stage.', 'Sturdy, doesn''t wobble. Holds my 16x20 canvas perfectly.'),
  ('Brass Desk Lamp Dimmable', 48, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=brass%20desk%20lamp%20dimmable%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Brass%20Desk%20Lamp%20Dimmable', NULL, ARRAY['for-him','for-her','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Warm LED, touch control. The light that makes work feel less like work.', 'Three brightness levels. The warmest one is perfect for evenings.'),
  ('Vinyl Record Frame', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=vinyl%20record%20frame%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Vinyl%20Record%20Frame', NULL, ARRAY['for-him','for-her','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Acrylic front, wall-mount. The album cover that''s actually art.', 'Now my favorite record is on the wall. Swapped it monthly.'),
  ('Macrame Wall Hanging', 28, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=macrame%20wall%20hanging%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Macrame%20Wall%20Hanging', NULL, ARRAY['for-her','for-friends','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Cotton rope, wooden dowel. The texture a blank wall needs.', 'Boho without being too much. The natural cotton looks organic.'),
  ('Floating Shelf Set of 3', 35, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=floating%20shelf%20set%20of%203%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Floating%20Shelf%20Set%20of%203', NULL, ARRAY['for-him','for-her','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Hidden brackets, solid wood. The clutter that became a display.', 'Installed in twenty minutes. Holds my books and plants, looks clean.'),
  ('Desk Clock Minimalist', 32, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=desk%20clock%20minimalist%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Desk%20Clock%20Minimalist', NULL, ARRAY['for-him','for-coworkers','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'mid', 'Silent sweep, metal frame. The timepiece that doesn''t tick.', 'No ticking sound. The minimalist face is calming on my desk.'),
  ('Terrarium Glass Globe', 24, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=terrarium%20glass%20globe%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Terrarium%20Glass%20Globe', NULL, ARRAY['for-her','for-friends','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Hang it, fill it. The tiny garden that hangs in the air.', 'Planted moss and a small fern. It''s alive and thriving.'),
  ('Vintage Map Print Framed', 29, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=vintage%20map%20print%20framed%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Vintage%20Map%20Print%20Framed', NULL, ARRAY['for-him','for-parents','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', '1900s world map, distressed finish. The wall that travels.', 'Quality print on thick paper. The frame is real wood.'),
  ('Ceramic Incense Holder', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=ceramic%20incense%20holder%2C%20on%20a%20white%20shelf%2C%20soft%20natural%20light%2C%20editorial%20interior%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Ceramic%20Incense%20Holder', NULL, ARRAY['for-her','for-friends','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Hand-glazed, catches ash. For the ritual that smells like calm.', 'Beautiful glaze, catches every speck of ash. Simple and elegant.');
INSERT INTO public.products (name, price, image_url, affiliate_url, asin, audience_tags, occasion_tags, price_range, description, review_quote) VALUES
  ('Entry-Level Turntable', 99, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=entry-level%20turntable%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Entry-Level%20Turntable', NULL, ARRAY['for-him','for-her','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'high', 'Bluetooth, built-in preamp. The record player that started it all.', 'Sound is warm, setup was easy. My vinyl collection finally has a home.'),
  ('Kalimba Thumb Piano', 25, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=kalimba%20thumb%20piano%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Kalimba%20Thumb%20Piano', NULL, ARRAY['for-kids','for-her','for-friends']::text[], ARRAY['birthday','christmas']::text[], 'cheap', '17 keys, acacia wood. The instrument you learn in five minutes.', 'Surprisingly soothing. My daughter and I play it every evening.'),
  ('Ukulele Starter Kit', 49, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=ukulele%20starter%20kit%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Ukulele%20Starter%20Kit', NULL, ARRAY['for-kids','for-friends','for-her']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Soprano size, tuner, bag, strings. The happy sound, ready to learn.', 'Stays in tune after a few days. Sounds bright and cheerful.'),
  ('Vinyl Record Cleaning Kit', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=vinyl%20record%20cleaning%20kit%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Vinyl%20Record%20Cleaning%20Kit', NULL, ARRAY['for-him','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Brush, fluid, cloth. For the records that sound dusty.', 'Cleaned my thrift-store finds. Crackle is gone. Worth it.'),
  ('Headphone Stand Aluminum', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=headphone%20stand%20aluminum%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Headphone%20Stand%20Aluminum', NULL, ARRAY['for-him','for-coworkers']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Solid base, minimal arm. The desk upgrade you didn''t know you needed.', 'Frees up desk space, looks sleek. My headphones have a home now.'),
  ('Guitar Capo Steel String', 14, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=guitar%20capo%20steel%20string%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Guitar%20Capo%20Steel%20String', NULL, ARRAY['for-him','for-friends','for-her']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Spring-loaded, no buzz. For the chord changes you can''t reach.', 'Holds firm on every fret. No tuning issues, easy to clip.'),
  ('Music Sheet Stand Folding', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=music%20sheet%20stand%20folding%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Music%20Sheet%20Stand%20Folding', NULL, ARRAY['for-kids','for-her','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Adjustable, travel bag included. The stand that goes where you go.', 'Light, sturdy, folds small. Holds a thick binder without tipping.'),
  ('Bluetooth Record Adapter', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=bluetooth%20record%20adapter%2C%20on%20a%20wooden%20surface%2C%20warm%20moody%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Bluetooth%20Record%20Adapter', NULL, ARRAY['for-him','for-her','for-friends']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Connects AirPods to your turntable. Wireless vinyl, no cables.', 'Paired instantly. I can listen to vinyl from across the room.'),
  ('Dog Bed Memory Foam', 49, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=dog%20bed%20memory%20foam%2C%20on%20a%20cream%20surface%2C%20soft%20light%2C%20editorial%20pet%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Dog%20Bed%20Memory%20Foam', NULL, ARRAY['for-friends','for-parents','for-her']::text[], ARRAY['birthday','christmas']::text[], 'mid', 'Orthopedic foam, washable cover. The nap spot they deserve.', 'My old dog sleeps deeper. The foam actually supports her joints.'),
  ('Cat Tunnel Collapsible', 19, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=cat%20tunnel%20collapsible%2C%20on%20a%20cream%20surface%2C%20soft%20light%2C%20editorial%20pet%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Cat%20Tunnel%20Collapsible', NULL, ARRAY['for-friends','for-her','for-kids']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Three tunnels, crinkle paper. The chaos your cat deserves.', 'My cat runs through it at 3am. She loves it. I''ve accepted it.'),
  ('Slow Feeder Bowl', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=slow%20feeder%20bowl%2C%20on%20a%20cream%20surface%2C%20soft%20light%2C%20editorial%20pet%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Slow%20Feeder%20Bowl', NULL, ARRAY['for-friends','for-parents']::text[], ARRAY['birthday','thanks']::text[], 'cheap', 'Maze pattern, no gulping. The dinner that takes twenty minutes.', 'My lab used to inhale food in 30 seconds. Now it takes 10 minutes.'),
