  ('Fountain Pen Medium Nib Sand Edition 6', 47, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=fountain%20pen%20medium%20nib%20sand%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Fountain%20Pen%20Medium%20Nib%20Sand%20Edition%206', NULL, ARRAY['for-parents','for-friends']::text[], ARRAY['thanks']::text[], 'mid', 'Cartridge or converter. The scratch of real ink on paper.', 'First fountain pen. The line is smooth, the ink flows. Writing feels different.');
INSERT INTO public.products (name, price, image_url, affiliate_url, asin, audience_tags, occasion_tags, price_range, description, review_quote) VALUES
  ('Leather Notebook Cover A5 Blush Edition 6', 62, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=leather%20notebook%20cover%20a5%20blush%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Leather%20Notebook%20Cover%20A5%20Blush%20Edition%206', NULL, ARRAY['for-friends']::text[], ARRAY['wedding']::text[], 'mid', 'Full-grain leather, refillable. Your notebook''s forever home.', 'Looks better scuffed. The elastic holds refills tight.'),
  ('Watercolor Pencil Set 24 Copper Edition 6', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=watercolor%20pencil%20set%2024%20copper%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Watercolor%20Pencil%20Set%2024%20Copper%20Edition%206', NULL, ARRAY['for-coworkers']::text[], ARRAY['newyear']::text[], 'cheap', 'Draw, then brush with water. Color that blooms.', 'Vibrant, smooth, blend beautifully. My sketchbook got interesting.'),
  ('Book Lovers Tea Sampler Brass Edition 6', 26, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=book%20lovers%20tea%20sampler%20brass%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Book%20Lovers%20Tea%20Sampler%20Brass%20Edition%206', NULL, ARRAY['for-him','for-her']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Six loose-leaf teas, each paired with a reading mood.', 'The ''rainy afternoon'' blend is my reading companion now.'),
  ('Desk Organizer Walnut Natural Edition 6', 45, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=desk%20organizer%20walnut%20natural%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Desk%20Organizer%20Walnut%20Natural%20Edition%206', NULL, ARRAY['for-her']::text[], ARRAY['christmas']::text[], 'mid', 'Solid wood, six slots. For the desk that wants to grow up.', 'Heavy, beautiful, and everything has a place now.'),
  ('Wax Seal Stamp Kit White Edition 6', 40, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=wax%20seal%20stamp%20kit%20white%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Wax%20Seal%20Stamp%20Kit%20White%20Edition%206', NULL, ARRAY['for-kids']::text[], ARRAY['anniversary']::text[], 'mid', 'Brass stamp, wax beads, melting spoon. Letters worth opening.', 'Sealed my wedding thank-you cards with this. People kept the envelopes.'),
  ('Bullet Dotted Notebook Graphite Edition 6', 16, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=bullet%20dotted%20notebook%20graphite%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Bullet%20Dotted%20Notebook%20Graphite%20Edition%206', NULL, ARRAY['for-parents','for-friends']::text[], ARRAY['thanks']::text[], 'cheap', '120gsm paper, no bleed-through. The system that actually sticks.', 'Dots instead of lines. Freedom to plan, sketch, and note in one place.'),
  ('Calligraphy Brush Pen Set Amber Edition 6', 11, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=calligraphy%20brush%20pen%20set%20amber%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Calligraphy%20Brush%20Pen%20Set%20Amber%20Edition%206', NULL, ARRAY['for-friends']::text[], ARRAY['wedding','newyear']::text[], 'cheap', 'Dual-tip, flexible brush. For the handwriting that wants to wander.', 'The pressure sensitivity is real. Lettering finally clicked.'),
  ('Reading Light Clip-On Warm Slate Edition 6', 37, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=reading%20light%20clip-on%20warm%20slate%20edition%206%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Reading%20Light%20Clip-On%20Warm%20Slate%20Edition%206', NULL, ARRAY['for-coworkers']::text[], ARRAY['newyear']::text[], 'mid', 'Amber light, three brightness levels. For the ''one more chapter'' nights.', 'No blue light, no disturbing partner. Clips to any book.'),
  ('Insulated Water Bottle 32oz Ivory Edition 6', 21, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=insulated%20water%20bottle%2032oz%20ivory%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Insulated%20Water%20Bottle%2032oz%20Ivory%20Edition%206', NULL, ARRAY['for-him','for-her']::text[], ARRAY['birthday']::text[], 'cheap', 'Keeps ice for 24 hours. The bottle that lives on your desk.', 'Left it in a hot car. Still had ice six hours later.'),
  ('Yoga Mat Cork Olive Edition 6', 39, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=yoga%20mat%20cork%20olive%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Yoga%20Mat%20Cork%20Olive%20Edition%206', NULL, ARRAY['for-her']::text[], ARRAY['christmas']::text[], 'mid', 'Natural cork surface, no slip. Better grip when wet.', 'No more sliding in downward dog. The cork feels grounded.'),
  ('Resistance Band Set Edition 6', 35, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=resistance%20band%20set%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Resistance%20Band%20Set%20Edition%206', NULL, ARRAY['for-kids']::text[], ARRAY['anniversary','thanks']::text[], 'mid', 'Five bands, door anchor, handles. The gym that fits in a drawer.', 'Surprised by the resistance. The red one is no joke.'),
  (' Camping Hammock Double Matte Black Edition 6', 31, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=%20camping%20hammock%20double%20matte%20black%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=%20Camping%20Hammock%20Double%20Matte%20Black%20Edition%206', NULL, ARRAY['for-parents','for-friends']::text[], ARRAY['thanks']::text[], 'mid', 'Parachute nylon, 500lb capacity. The park just became a bedroom.', 'Packs to the size of a grapefruit. Set up in two minutes.'),
  ('Insulated Travel Mug 16oz Walnut Edition 6', 60, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=insulated%20travel%20mug%2016oz%20walnut%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Insulated%20Travel%20Mug%2016oz%20Walnut%20Edition%206', NULL, ARRAY['for-friends']::text[], ARRAY['wedding']::text[], 'mid', 'Keeps coffee hot from nine to three.', 'He forgets to drink water. Let the mug remind him instead of you.'),
  ('Folding Camp Chair Oak Edition 6', 51, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=folding%20camp%20chair%20oak%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Folding%20Camp%20Chair%20Oak%20Edition%206', NULL, ARRAY['for-coworkers']::text[], ARRAY['newyear']::text[], 'mid', 'Aluminum frame, cup holder, packs flat. Your backstage seat anywhere.', 'Lighter than expected. The cup holder is the real luxury.'),
  ('Jump Rope Weighted Cream Edition 6', 27, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=jump%20rope%20weighted%20cream%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Jump%20Rope%20Weighted%20Cream%20Edition%206', NULL, ARRAY['for-him','for-her']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Steel cable, ball bearing. The cardio you can do in 10 square feet.', 'Fast, smooth, no tangling. Calves burning in 3 minutes.'),
  ('Golf Towel Microfiber Sage Green Edition 6', 14, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=golf%20towel%20microfiber%20sage%20green%20edition%206%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Golf%20Towel%20Microfiber%20Sage%20Green%20Edition%206', NULL, ARRAY['for-her']::text[], ARRAY['christmas']::text[], 'cheap', 'Tri-fold, carabiner clip. For the golfer who cares about their clubs.', 'Absorbs moisture without scratching. The clip stays put.'),
