  ('Board Game Strategy Set Charcoal Edition 6', 75, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=board%20game%20strategy%20set%20charcoal%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Board%20Game%20Strategy%20Set%20Charcoal%20Edition%206', NULL, ARRAY['for-friends']::text[], ARRAY['wedding','newyear']::text[], 'high', 'For the game night that doesn''t end at Monopoly.', 'Played three rounds straight. The strategy depth is real.'),
  ('1000 Piece Puzzle Art Sand Edition 6', 20, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=1000%20piece%20puzzle%20art%20sand%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=1000%20Piece%20Puzzle%20Art%20Sand%20Edition%206', NULL, ARRAY['for-coworkers']::text[], ARRAY['newyear']::text[], 'cheap', 'Riverside scene, matte finish. The quiet weekend activity.', 'Took us four evenings. The satisfaction of the last piece is worth it.'),
  ('Building Blocks Classic Blush Edition 6', 37, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=building%20blocks%20classic%20blush%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Building%20Blocks%20Classic%20Blush%20Edition%206', NULL, ARRAY['for-him','for-her']::text[], ARRAY['birthday']::text[], 'mid', '500 pieces, six colors. For the engineer who hasn''t retired.', 'My 8-year-old built a spaceship. My 38-year-old self helped.'),
  ('Card Game Party Pack Copper Edition 6', 31, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=card%20game%20party%20pack%20copper%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Card%20Game%20Party%20Pack%20Copper%20Edition%206', NULL, ARRAY['for-her']::text[], ARRAY['christmas']::text[], 'mid', 'Three games, 2-8 players. The icebreaker that actually breaks ice.', 'Played with strangers. We were laughing in five minutes.'),
  ('Wooden Brain Teaser Set Brass Edition 6', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=wooden%20brain%20teaser%20set%20brass%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Wooden%20Brain%20Teaser%20Set%20Brass%20Edition%206', NULL, ARRAY['for-kids']::text[], ARRAY['anniversary','thanks']::text[], 'cheap', 'Six metal and wood puzzles. For the mind that needs a walk.', 'Some took minutes, one took days. All satisfying to solve.'),
  ('RC Stunt Car Natural Edition 6', 22, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=rc%20stunt%20car%20natural%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=RC%20Stunt%20Car%20Natural%20Edition%206', NULL, ARRAY['for-parents','for-friends']::text[], ARRAY['thanks']::text[], 'cheap', 'Flips, spins, climbs. The remote control car that grew up.', 'My kid drove it down the stairs. Still works. Sturdy is an understatement.'),
  ('Art Kit for Kids 120pcs White Edition 6', 26, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=art%20kit%20for%20kids%20120pcs%20white%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Art%20Kit%20for%20Kids%20120pcs%20White%20Edition%206', NULL, ARRAY['for-friends']::text[], ARRAY['wedding']::text[], 'cheap', 'Crayons, markers, paints, paper. The creative explosion in a box.', 'Everything in one case. My 6-year-old opened it and didn''t surface for hours.'),
  ('Stargazing Telescope Entry Graphite Edition 6', 97, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=stargazing%20telescope%20entry%20graphite%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Stargazing%20Telescope%20Entry%20Graphite%20Edition%206', NULL, ARRAY['for-coworkers']::text[], ARRAY['newyear']::text[], 'high', '70mm aperture, tripod, phone adapter. The moon, up close.', 'Saw Saturn''s rings. My kids thought it was a picture. It wasn''t.'),
  ('Jigsaw Puzzle Map World Amber Edition 6', 20, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=jigsaw%20puzzle%20map%20world%20amber%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Jigsaw%20Puzzle%20Map%20World%20Amber%20Edition%206', NULL, ARRAY['for-him','for-her']::text[], ARRAY['birthday','christmas']::text[], 'cheap', 'Vintage world map, 500 pieces. Geography you can touch.', 'My son now knows where Mongolia is. That''s the power of a puzzle.'),
  ('Magnetic Dart Board Slate Edition 6', 29, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=magnetic%20dart%20board%20slate%20edition%206%2C%20on%20a%20cream%20surface%2C%20bright%20soft%20light%2C%20editorial%20product%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Magnetic%20Dart%20Board%20Slate%20Edition%206', NULL, ARRAY['for-her']::text[], ARRAY['christmas']::text[], 'cheap', 'No sharp points, no wall holes. The office tournament starter.', 'Safer than real darts, almost as satisfying. The magnets stick well.'),
  ('Gourmet Chocolate Box 24pc Ivory Edition 6', 67, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=gourmet%20chocolate%20box%2024pc%20ivory%20edition%206%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Gourmet%20Chocolate%20Box%2024pc%20Ivory%20Edition%206', NULL, ARRAY['for-kids']::text[], ARRAY['anniversary']::text[], 'mid', 'Single-origin, hand-tempered. The box that doesn''t last.', 'The sea salt caramel disappeared first. The dark cherry was my favorite.'),
  ('Coffee Bean Sampler 1lb Olive Edition 6', 32, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=coffee%20bean%20sampler%201lb%20olive%20edition%206%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Coffee%20Bean%20Sampler%201lb%20Olive%20Edition%206', NULL, ARRAY['for-parents','for-friends']::text[], ARRAY['thanks']::text[], 'mid', 'Three origins, whole bean. For the cup that''s never the same.', 'The Ethiopian blew me away. Blueberry in coffee? Yes.'),
  ('Honey Trio Gift Set Edition 6', 44, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=honey%20trio%20gift%20set%20edition%206%2C%20on%20a%20wooden%20board%2C%20rustic%20styling%2C%20editorial%20food%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Honey%20Trio%20Gift%20Set%20Edition%206', NULL, ARRAY['for-friends']::text[], ARRAY['wedding','newyear']::text[], 'mid', 'Wildflower, clover, buckwheat. Three honeys, three toast moods.', 'The buckwheat is dark and malty. Never knew honey could taste like this.'),
