  ('Desk Organizer Walnut Terracotta Edition 7', 41, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=desk%20organizer%20walnut%20terracotta%20edition%207%2C%20on%20a%20wooden%20desk%2C%20warm%20light%2C%20flat%20lay%20editorial%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Desk%20Organizer%20Walnut%20Terracotta%20Edition%207', NULL, ARRAY['for-kids']::text[], ARRAY['anniversary']::text[], 'mid', 'Solid wood, six slots. For the desk that wants to grow up.', 'Heavy, beautiful, and everything has a place now.'),
