  ('Insulated Water Bottle 32oz Copper Edition 7', 54, 'https://trae-api-cn.mchost.guru/api/ide/v1/text_to_image?prompt=insulated%20water%20bottle%2032oz%20copper%20edition%207%2C%20on%20a%20rocky%20surface%2C%20golden%20hour%20light%2C%20editorial%20outdoor%20photography&image_size=landscape_4_3', 'https://www.amazon.com/s?k=Insulated%20Water%20Bottle%2032oz%20Copper%20Edition%207', NULL, ARRAY['for-her']::text[], ARRAY['christmas']::text[], 'mid', 'Keeps ice for 24 hours. The bottle that lives on your desk.', 'Left it in a hot car. Still had ice six hours later.'),
